function toast(message,undo=false){const el=$('#toast');el.textContent=message;if(undo){const button=document.createElement('button');button.type='button';button.dataset.action='undo-sticker';button.textContent='Отменить';el.append(button);}el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),undo?12000:5000);}
function storeSession(value){state.session=value;try{value?sessionStorage.setItem('product_hub_session',JSON.stringify(value)):sessionStorage.removeItem('product_hub_session');}catch{}}
async function api(path,{method='GET',body,headers={},binary=false}={}){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),90000);
 const h={...headers};if(state.session?.token)h.Authorization=`Bearer ${state.session.token}`;
 if(body!==undefined&&!(body instanceof Blob)&&!(body instanceof Uint8Array)&&!(body instanceof FormData)){h['Content-Type']='application/json';body=JSON.stringify(body);}
 try{
  const r=await fetch(API+path,{method,headers:h,body,signal:controller.signal,credentials:'omit',cache:'no-store'});
  if(!r.ok){let message='Не удалось выполнить запрос';try{message=(await r.json()).error||message;}catch{}
   if(r.status===401&&path!=='/login'){storeSession(null);state.current=null;state.dirty=false;renderLogin(message);}
   throw new Error(message);
  }return binary?await r.blob():await r.json();
 }catch(e){if(e.name==='AbortError')throw new Error('Сервер отвечает дольше обычного. Попробуйте ещё раз.');if(e instanceof TypeError)throw new Error('Нет связи с сервером. Проверьте интернет и повторите действие.');throw e;}finally{clearTimeout(timer);}
}
