function shell(){
 const counts={all:lineGroups(state.products.filter(p=>!p.archived)).length,work:state.products.filter(p=>!p.archived&&['draft','documents'].includes(p.stage)).length,review:state.products.filter(p=>!p.archived&&p.stage==='review').length,archive:state.products.filter(p=>p.archived).length};
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar">${brand()}<div class="nav-label">ПРОЕКТЫ</div><nav class="nav" aria-label="Разделы товаров">${[['all','grid','Все линейки'],['work','clock','В работе'],['review','check','На согласовании'],['archive','archive','Архив']].map(([key,ic,label])=>`<button data-action="filter" data-value="${key}" class="${state.filter===key?'active':''}">${icon(ic)}${label}<span class="count">${counts[key]}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button data-action="access" title="Настройки доступа">${icon('settings')} Настройки доступа</button><button data-action="logout" title="Выйти">${icon('logout')} Выйти из кабинета</button><div class="account"><div class="avatar">К</div><div><strong>${esc(state.session?.login||'Команда')}</strong><small>Общий аккаунт</small></div></div></div></aside><main class="main" id="main"></main></div>`;
}
function lineKey(p){return p.line_id||p.id;}
function lineGroups(products=state.products){const groups=new Map();for(const p of products){const key=lineKey(p);if(!groups.has(key))groups.set(key,{id:key,title:p.line_title||p.title,revision:p.line_revision||0,products:[]});groups.get(key).products.push(p);}return [...groups.values()];}
function getLine(key){return lineGroups().find(x=>x.id===key);}
function visibleProducts(){let rows=state.products.filter(p=>state.filter==='archive'?p.archived:!p.archived);if(state.filter==='work')rows=rows.filter(p=>['draft','documents'].includes(p.stage));if(state.filter==='review')rows=rows.filter(p=>p.stage==='review');const q=state.search.toLocaleLowerCase('ru').trim();return rows.filter(p=>`${p.title} ${p.line_title||''} ${p.sku} ${p.category}`.toLocaleLowerCase('ru').includes(q));}
function renderLine(key){
 const g=getLine(key);if(!g){renderList();return;}state.current=null;state.line=key;state.dirty=false;const rows=g.products.filter(p=>state.filter==='archive'?p.archived:!p.archived),source=rows.find(p=>!p.archived);const u=new URL(location.href);u.searchParams.delete('product');u.searchParams.set('line',key);history.replaceState(null,'',u);shell();
 $('#main').innerHTML=`<div class="topline"><button class="crumb" data-action="all-lines">${icon('arrow')} Все линейки</button><span class="tag">Линейка товаров</span></div><header class="page-head"><div><h1>${esc(g.title)}</h1><p>Отдельная карточка, документы и макеты для каждого варианта</p><button class="text-button" data-action="rename-line" data-id="${g.id}">Изменить название линейки</button></div>${source?`<button class="btn primary" data-action="add-variant" data-id="${source.id}">${icon('plus')} Добавить товар из линейки</button>`:''}</header><div class="cards variant-cards">${rows.map(p=>`<article class="product-card variant-card" tabindex="0" role="button" data-action="open" data-id="${p.id}" aria-label="Открыть ${esc(p.title)}"><div class="card-cover"><span class="badge ${p.stage}">${p.archived?'В архиве':STAGES[p.stage]}</span>${icon('box')}</div><div class="card-body"><h3>${esc(p.title)}</h3><span class="sku">${esc(p.sku||'Артикул не указан')}</span><dl class="variant-facts"><div><dt>В упаковке</dt><dd>${esc(p.fields.units_per_pack||'—')}</dd></div><div><dt>В коробе</dt><dd>${esc(p.fields.packs_per_carton||'—')}</dd></div></dl><div class="progress-info"><span>Заполнение карточки</span><span>${progress(p)}%</span></div><div class="progress-track"><span style="width:${progress(p)}%"></span></div></div></article>`).join('')}</div>`;window.scrollTo(0,0);
}
function variantNav(){const p=state.current,g=getLine(lineKey(p));if(!g)return '';return `<nav class="variant-nav" aria-label="Товары из линейки">${g.products.filter(x=>!x.archived||x.id===p.id).map(x=>`<button class="variant-chip ${x.id===p.id?'active':''}" data-action="open" data-id="${x.id}">${esc(x.title)}</button>`).join('')}${!p.archived?`<button class="variant-chip add" data-action="add-variant" data-id="${p.id}" aria-label="Добавить товар из линейки">${icon('plus')} Добавить вариант</button>`:''}</nav>`;}
function variantDialog(sourceId){const source=state.products.find(p=>p.id===sourceId);if(!source)return;const rows=getLine(lineKey(source)).products.filter(p=>!p.archived);dialog(`${modalHead('Добавить товар из линейки')}<p class="subtle">Скопируются описания, заводы, переводы, конкуренты, стикеры и общие документы. Артикул, штрихкоды, вложимость, макеты и вырубки будут пустыми.</p><form id="variant-form"><label class="field"><span>Скопировать из</span><select name="source">${rows.map(p=>`<option value="${p.id}" ${p.id===sourceId?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label><label class="field"><span>Название нового варианта</span><input name="title" maxlength="200" required placeholder="Например, Листы для стирки, 50 шт."></label><p class="error" id="modal-error" role="alert"></p><div class="dialog-actions"><button class="btn" type="button" data-action="close">Отмена</button><button class="btn primary" type="submit">Добавить вариант</button></div></form>`);}
function renameLine(key){const g=getLine(key);if(!g)return;dialog(`${modalHead('Название линейки')}<form id="line-form" data-id="${key}" data-revision="${g.revision}"><label class="field"><span>Название</span><input name="title" required maxlength="200" value="${esc(g.title)}"></label><p class="error" id="modal-error" role="alert"></p><div class="dialog-actions"><button class="btn" type="button" data-action="close">Отмена</button><button class="btn primary" type="submit">Сохранить</button></div></form>`);}
function markImage(m){return new URL('/portal/'+m.src.replace(/^\.\//,''),new URL(API,location.href).origin).href;}
function markPicture(m){return m.custom?`<span class="custom-mark-placeholder" data-mark-image="${m.id}" aria-label="Загружаем картинку">${icon('file')}</span>`:`<img src="${markImage(m)}" alt="${esc(m.label)}" loading="lazy">`;}
async function hydrateMarkImages(){
 const nodes=[...document.querySelectorAll('[data-mark-image]')];await Promise.all(nodes.map(async node=>{const id=node.dataset.markImage;
  try{if(!customMarkImages.has(id)){const task=api('/markings/'+id+'/image',{binary:true}).then(blob=>URL.createObjectURL(blob));customMarkImages.set(id,task);task.catch(()=>customMarkImages.delete(id));}const url=await customMarkImages.get(id);if(!node.isConnected)return;const img=new Image();img.src=url;img.alt=state.markings.find(m=>m.id===id)?.label||'Значок маркировки';node.replaceWith(img);}catch{if(node.isConnected){node.textContent='Не удалось загрузить картинку';node.classList.add('mark-image-error');}}
 }));
}
function markBox(kind){const selected=state.markings.filter(m=>state.current.details[kind].includes(m.id)),archived=state.current.archived;return `<div class="mark-selection" id="mark-box-${kind}"><div class="mark-selection-head"><strong>${MARKING_SECTIONS[kind]}</strong>${!archived?`<button class="btn small" data-action="choose-marks" data-kind="${kind}">${icon('plus')} Выбрать значки</button>`:''}</div><div class="selected-marks">${selected.length?selected.map(m=>`<div class="selected-mark">${markPicture(m)}<span>${esc(m.label)}</span>${m.description?`<small>${esc(m.description)}</small>`:''}</div>`).join(''):'<p class="subtle">Значки не выбраны</p>'}</div></div>`;}
function renderMarkBoxes(){if(!state.current)return;for(const kind of Object.keys(MARKING_SECTIONS)){const box=$('#mark-box-'+kind);if(box)box.outerHTML=markBox(kind);}hydrateMarkImages();}
async function chooseMarks(kind,refresh=true){
 if(!state.current||state.current.archived||!MARKING_SECTIONS[kind])return;const id=state.current.id;
 if(refresh){const catalog=await api('/catalog');if(state.current?.id!==id)return;state.markings=catalog.markings;state.factories=catalog.factories;}
 const selected=state.current.details[kind];dialog(`${modalHead(MARKING_SECTIONS[kind])}<p class="subtle">Выберите нужные значки. Изменения сохраняются вместе с карточкой товара.</p><div class="marks-toolbar"><input id="marks-search" placeholder="Поиск по названию или описанию" aria-label="Поиск значка"><select id="marks-category" aria-label="Категория значков"><option value="">Все категории</option>${[...new Set([...MARKING_CATEGORIES,...state.markings.map(m=>m.category)])].map(x=>`<option ${kind==='material_marks'&&x==='Материал упаковки'?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div id="marks-grid" class="marks-grid" data-kind="${kind}">${state.markings.map(m=>`<label class="mark-option" data-mark-label="${esc((m.label+' '+(m.description||'')).toLocaleLowerCase('ru'))}" data-mark-category="${esc(m.category)}"><input type="checkbox" data-mark-id="${m.id}" data-mark-kind="${kind}" ${selected.includes(m.id)?'checked':''}>${markPicture(m)}<span>${esc(m.label)}</span>${m.description?`<small>${esc(m.description)}</small>`:''}</label>`).join('')}</div><div class="marks-source">Каталоги: <a href="https://artsdelka.ru/packaging-marking" target="_blank" rel="noopener noreferrer">artsdelka.ru</a>, <a href="https://pro-color.ru/assets/migrated/blog/bbb1a69b_Markirovka_RoSK-1.jpg" target="_blank" rel="noopener noreferrer">материалы упаковки</a>. Свои значки видны команде.</div><div class="dialog-actions marks-dialog-actions"><button class="btn" data-action="new-mark" data-kind="${kind}">${icon('plus')} Добавить свой значок</button><button class="btn primary" data-action="finish-marks">Готово</button></div>`);$('#modal').classList.add('marks-dialog');filterMarks();hydrateMarkImages();
}
function filterMarks(){const q=$('#marks-search').value.trim().toLocaleLowerCase('ru'),cat=$('#marks-category').value;document.querySelectorAll('.mark-option').forEach(el=>el.hidden=!(el.dataset.markLabel.includes(q)&&(!cat||el.dataset.markCategory===cat)));}
function newMarkDialog(kind){
 dialog(`${modalHead('Добавить свой значок')}<p class="subtle">Картинка и описание сохранятся в общем списке маркировки. Значок можно использовать в других товарах.</p><form id="marking-form" data-kind="${kind}" data-product-id="${state.current.id}"><label class="field"><span>Название значка</span><input name="label" required maxlength="200" placeholder="Например, 04 · PE-LD"></label><label class="field"><span>Категория</span><select name="category">${MARKING_CATEGORIES.map(c=>`<option ${c===(kind==='material_marks'?'Материал упаковки':'Другие знаки')?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field"><span>Описание маркировки</span><textarea name="description" rows="3" maxlength="3000" placeholder="Материал, расшифровка или пояснение"></textarea></label><label class="field"><span>Картинка значка</span><input type="file" id="marking-image" name="image" accept="image/png,image/jpeg,image/webp" required><em>PNG, JPG или WebP, до 20 МБ. Картинка будет подготовлена автоматически.</em></label><div class="mark-upload-preview"><img id="custom-mark-preview" hidden alt="Предпросмотр своего значка"></div><p class="error" id="modal-error" role="alert"></p><div class="dialog-actions"><button class="btn" type="button" data-action="back-to-marks" data-kind="${kind}">Назад</button><button class="btn primary" type="submit">Добавить и выбрать</button></div></form>`);
}
async function prepareMarkImage(file){
 if(!file||!file.size)throw new Error('Выберите картинку');if(file.size>20*1024*1024)throw new Error('Картинка должна быть не больше 20 МБ');
 const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('Не удалось открыть картинку. Используйте PNG, JPG или WebP.'));im.src=url;});const scale=Math.min(768/img.naturalWidth,768/img.naturalHeight,1),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Не удалось подготовить картинку')),'image/png'));}finally{URL.revokeObjectURL(url);}
}
async function saveMark(form,values){
 const id=form.dataset.productId,kind=form.dataset.kind;state.markingSaving=true;try{const image=await prepareMarkImage(values.image),body=new FormData();body.set('label',values.label);body.set('category',values.category);body.set('description',values.description);body.set('image',image,'mark.png');const mark=await api('/markings',{method:'POST',body});state.markings.push(mark);if(state.current?.id===id){state.current.details[kind].push(mark.id);markDirty();await chooseMarks(kind,false);}toast('Значок добавлен и выбран. Сохраните карточку товара.');}finally{state.markingSaving=false;}
}
