async function saveDesignerBrief(){if(state.briefBusy)return false;briefLock(true);try{state.brief=await api(`/products/${state.current.id}/designer-brief`,{method:'PUT',body:{revision:state.brief.revision,content:state.brief.content}});state.briefDirty=false;if($('#brief-save-state'))$('#brief-save-state').textContent='ТЗ сохранено';return true;}catch(e){$('#brief-error').textContent=e.message;return false;}finally{briefLock(false);}}
async function downloadDesignerBrief(){if(state.briefBusy)return;if((state.briefDirty||state.brief.revision===0)&&!await saveDesignerBrief())return;briefLock(true);try{const c=state.brief.content,file=state.files.find(f=>f.id===c.layout_file_id);if(c.include_layout&&file)await getLayoutPreview(file).catch(()=>{});const blob=await api(`/products/${state.current.id}/designer-brief/export.docx?revision=${state.brief.revision}`,{binary:true});downloadBlob(blob,c.title.replace(/[<>:"/\\|?*]/g,'_')+'.docx');toast('ТЗ для дизайнера готово');}catch(e){$('#brief-error').textContent=e.message;}finally{briefLock(false);}}
