function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function getLayoutPreview(file){
 if(previewCache.has(file.id))return previewCache.get(file.id);
 const task=(async()=>{
  let png;if(file.has_preview){try{png=await api(`/files/${file.id}/thumbnail`,{binary:true});}catch{}}
  if(!png){
   const blob=await api('/files/'+file.id,{binary:true});const canvas=document.createElement('canvas');
   if(file.mime==='application/pdf'||/\.pdf$/i.test(file.name)){
    const pdfjs=await import('./pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./pdf.worker.mjs',import.meta.url).href;
    const task=pdfjs.getDocument({data:new Uint8Array(await blob.arrayBuffer()),useSystemFonts:true,isEvalSupported:false,useWasm:false}),doc=await task.promise;
    try{const page=await doc.getPage(1),base=page.getViewport({scale:1}),viewport=page.getViewport({scale:Math.min(900/base.width,900/base.height,2)});canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await page.render({canvas,viewport}).promise;}finally{await task.destroy();}
   }else{
    const url=URL.createObjectURL(blob);try{const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('Этот формат макета не поддерживает предпросмотр'));im.src=url;});const scale=Math.min(900/img.naturalWidth,900/img.naturalHeight,1);canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);}finally{URL.revokeObjectURL(url);}
   }
   png=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Не удалось создать предпросмотр')),'image/png'));
   if(!state.current?.archived)await api(`/files/${file.id}/thumbnail`,{method:'POST',body:png,headers:{'Content-Type':'image/png'}}).then(()=>file.has_preview=true).catch(()=>{});
  }
  return URL.createObjectURL(png);
 })();previewCache.set(file.id,task);task.catch(()=>previewCache.delete(file.id));return task;
}
async function hydrateConceptPhoto(){const id=state.current?.id,file=chosenLayout(state.files),box=$('#concept-photo');if(!box)return;if(!file)return;box.innerHTML=`<div class="photo-placeholder">${icon('refresh')}<strong>Готовим предпросмотр</strong><span>${esc(file.name)}</span></div>`;try{const url=await getLayoutPreview(file);if(state.current?.id!==id||state.tab!=='concept'||!$('#concept-photo'))return;$('#concept-photo').innerHTML=`<img src="${url}" alt="Актуальный макет ${esc(state.current.title)}"><div class="photo-caption"><span>${file.slot==='final'?'Итоговый':'Предварительный'} макет</span><small>${esc(file.name)}</small></div>`;}catch(e){console.warn('Не удалось создать предпросмотр макета:',e.message);if(state.current?.id===id&&state.tab==='concept'&&$('#concept-photo'))$('#concept-photo').innerHTML=`<div class="photo-placeholder">${icon('file')}<strong>${esc(file.name)}</strong><span>Для предпросмотра используйте PNG, JPG или PDF.</span><button class="btn small" data-action="download" data-id="${file.id}">Скачать макет</button></div>`;}}
