function renderList(){
 state.current=null;state.line=null;state.dirty=false;const u=new URL(location.href);u.searchParams.delete('product');u.searchParams.delete('line');history.replaceState(null,'',u);shell();
 const active=state.products.filter(p=>!p.archived),heading={all:'Линейки товаров',work:'В работе',review:'На согласовании',archive:'Архив товаров'}[state.filter];
 $('#main').innerHTML=`<div class="topline"><div class="eyebrow">РАБОЧЕЕ ПРОСТРАНСТВО / ЛИНЕЙКИ</div><span class="tag">Общий доступ команды</span></div><header class="page-head"><div><h1>${heading}</h1><p>Одна линейка — несколько вариантов товара</p></div><button class="btn primary" data-action="new">${icon('plus')} Добавить линейку</button></header><div class="stats">${[['Линеек',lineGroups(active).length,'box'],['Вариантов товаров',active.length,'grid'],['На согласовании',active.filter(p=>p.stage==='review').length,'file'],['Утверждено',active.filter(p=>['approved','production'].includes(p.stage)).length,'check']].map(([label,n,ic])=>`<div class="stat"><div><p>${label}</p><strong>${String(n).padStart(2,'0')}</strong></div><div class="mini-icon">${icon(ic)}</div></div>`).join('')}</div><div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Поиск товаров" placeholder="Найти линейку, вариант или артикул" value="${esc(state.search)}"></label><select id="sort" aria-label="Порядок товаров"><option value="updated">Сначала обновлённые</option><option value="name" ${state.sort==='name'?'selected':''}>По названию</option><option value="progress" ${state.sort==='progress'?'selected':''}>По заполнению</option></select></div><div class="list-label" id="list-label"></div><div class="cards" id="cards"></div>`;renderCards();
}
function renderCards(){
 const groups=lineGroups(visibleProducts());groups.sort(state.sort==='name'?((a,b)=>a.title.localeCompare(b.title,'ru')):state.sort==='progress'?((a,b)=>Math.max(...b.products.map(progress))-Math.max(...a.products.map(progress))):((a,b)=>Math.max(...b.products.map(p=>p.updated_at))-Math.max(...a.products.map(p=>p.updated_at))));$('#list-label').textContent=`Линеек: ${groups.length}`;
 $('#cards').innerHTML=groups.length?groups.map(g=>{const p=g.products[0],percent=Math.round(g.products.reduce((n,p)=>n+progress(p),0)/g.products.length);return `<article class="product-card" tabindex="0" role="button" data-action="open-line" data-id="${g.id}" aria-label="Открыть линейку ${esc(g.title)}"><div class="card-cover"><span class="badge documents">Линейка · вариантов: ${g.products.length}</span>${icon('box')}</div><div class="card-body"><div class="card-category">${esc(p.category||'Новая линейка')}</div><h3>${esc(g.title)}</h3><div class="line-preview">${g.products.slice(0,3).map(p=>`<span>${esc(p.title)}</span>`).join('')}${g.products.length>3?`<span>Ещё ${g.products.length-3}</span>`:''}</div><div class="progress-info"><span>Заполнение карточек</span><span>${percent}%</span></div><div class="progress-track"><span style="width:${percent}%"></span></div><div class="card-foot"><span>${esc(p.fields.owner||'Команда')}</span><span>${date(Math.max(...g.products.map(p=>p.updated_at)))}</span></div></div></article>`;}).join(''):`<div class="empty"><div class="empty-icon">${icon('box')}</div><h2>${state.search?'Ничего не найдено':'Добавьте линейку товаров'}</h2><p>Внутри линейки можно создавать варианты с разной вложимостью и своими макетами.</p>${!state.search?'<button class="btn primary" data-action="new">Добавить линейку</button>':''}</div>`;
}
function field(key,label,hint='',type='input',full=false){const p=state.current,value=['title','sku','category','stage'].includes(key)?p[key]:fieldValue(p,key),attr=`data-field="${key}" ${p.archived?'disabled':''}`;let control;if(type==='textarea')control=`<textarea ${attr} rows="3" maxlength="5000" placeholder="${esc(hint)}">${esc(value)}</textarea>`;else if(type==='stage')control=`<select ${attr}>${Object.entries(STAGES).map(([k,v])=>`<option value="${k}" ${k===value?'selected':''}>${v}</option>`).join('')}</select>`;else if(type==='honest')control=`<select ${attr}><option value="">Выберите</option><option value="yes" ${value==='yes'?'selected':''}>Нужен</option><option value="no" ${value==='no'?'selected':''}>Не нужен</option></select>`;else control=`<input ${attr} maxlength="${key==='title'?200:['sku','category'].includes(key)?100:5000}" ${['barcode','carton_barcode'].includes(key)?'inputmode="numeric"':''} value="${esc(value)}" placeholder="${esc(hint)}">`;return `<label class="field ${full?'full':''}"><span>${label}</span>${control}</label>`;}
const panel=(n,title,description,content)=>`<section class="panel"><div class="section-num">${n}</div><h2>${title}</h2>${description?`<p class="subtle">${description}</p>`:''}<div class="form-grid">${content}</div></section>`;
function concept(){return `<section class="concept-hero"><div class="concept-photo" id="concept-photo"><div class="photo-placeholder">${icon('file')}<strong>Макет товара</strong><span>Актуальный итоговый макет, а если его нет — предварительный</span></div></div><div class="concept-main"><div class="eyebrow">КОНЦЕПЦИЯ ТОВАРА</div><h2>Название и образ продукта</h2>${field('title','Название товара','Рабочее название варианта')+field('brand','Бренд','YokoSun')}<div class="form-grid">${field('sku','Артикул','Код варианта')+field('stage','Этап','','stage')+field('category','Категория')+field('owner','Ответственный')}</div></div></section>`+panel('01 / ИДЕЯ','Что это за товар','Информация, с которой начинается разработка.',field('purpose','Что это за товар','Что предлагаем покупателю','textarea',true)+field('benefit','Наши конкурентные преимущества','Чем отличаемся от других товаров','textarea',true)+field('audience','Целевая аудитория','Кому предназначен товар','textarea',true))+panel('02 / СВОЙСТВА','Какие свойства имеет товар','Аромат, текстура и другие характеристики продукта.',field('fragrance','Аромат','Без отдушки или название аромата')+field('texture','Текстура','Мягкость, консистенция, ощущение')+field('properties','Другие свойства','Что ещё важно при разработке','textarea',true))+panel('03 / ЛИЦЕВАЯ СТОРОНА','Что пишем на лицевой стороне','Формулировки для дизайнера.',field('front_text','Текст лицевой стороны','Название, свойства и ключевые сообщения','textarea',true));}
function specs(){return panel('01 / ПРОДУКТ','Финальные свойства','Заполните значения, подтверждённые заводом.',field('factory','Утверждённый завод','Название и адрес производства')+field('volume','Объём или масса','Значение и единица измерения')+field('dimensions','Размеры продукта','Длина × ширина × высота')+field('fragrance','Аромат','Название аромата или «Без отдушки»')+field('texture','Мягкость и текстура','Согласованные характеристики')+field('material','Материал или состав','Данные для упаковки')+field('properties','Остальные свойства','Все согласованные свойства продукта','textarea',true))+panel('02 / УПАКОВКА','Вложимость','Укажите обе величины: они используются в макетах и спецификации.',field('units_per_pack','Вложимость в упаковку','Количество изделий в одной упаковке')+field('packs_per_carton','Вложимость в короб','Количество потребительских упаковок в коробе'))+panel('03 / МАРКИРОВКА','Все компоненты отдельно','Для отсутствующих элементов укажите «Не применимо».',field('mark_container','Тара или корпус','Что наносим и где','textarea')+field('mark_lid','Крышка или колпачок','Обязательно проверьте маркировку крышки','textarea')+field('mark_label','Этикетка или внешняя упаковка','Тексты, знаки и расположение','textarea')+field('mark_carton','Транспортный короб','Маркировка и расположение','textarea')+field('mark_other','Другие элементы','Перечислите компоненты или «Не применимо»','textarea',true));}
function fileRow(f,current){
 const locked=state.current.archived||state.uploading||state.selecting;
 return `<div class="document-file ${current?'is-current latest-file':''}" data-file-id="${f.id}">${icon('file')}<div class="document-info"><div class="document-name-row"><div class="file-name">${esc(f.name)}</div>${current?'<span class="current-badge">Актуальный</span>':''}</div><div class="file-meta">${time(f.created_at)} · ${size(f.size)}</div><div class="file-actions"><button class="btn small" data-action="download" data-id="${f.id}" aria-label="Скачать ${esc(f.name)}">${icon('download')} Скачать</button>${f.mime.startsWith('image/')?`<button class="btn small" data-action="preview" data-id="${f.id}" aria-label="Посмотреть ${esc(f.name)}">${icon('eye')} Фото</button>`:''}${!current&&!state.current.archived?`<button class="btn small select-current" data-action="set-current" data-id="${f.id}" aria-label="Сделать актуальным: ${esc(f.name)}" ${locked?'disabled':''}>${icon('check')} ${state.selecting===f.id?'Сохраняем…':'Сделать актуальным'}</button>`:''}</div></div></div>`;
}
function filesView(){return `<p class="subtle">Можно загрузить несколько документов сразу, до 25 МБ каждый. Выберите нужный кнопкой «Сделать актуальным». Новые загрузки сохраняют текущий выбор; первый файл в пустом разделе отмечается автоматически.</p><div class="file-grid">${Object.entries(SLOTS).map(([slot,name])=>{
 const fs=state.files.filter(f=>f.slot===slot).sort((a,b)=>b.revision-a.revision),current=fs.find(f=>f.is_current)??fs[0],status=state.current.fields['doc_'+slot]||'required',busy=state.uploading?.slot===slot;
 const ordered=current?[current,...fs.filter(f=>f.id!==current.id)]:[];
 return `<section class="file-card" data-file-slot="${slot}"><div class="file-title"><h3>${name}</h3><select data-field="doc_${slot}" aria-label="Статус ${name}" ${state.current.archived?'disabled':''}>${[['required','Требуется'],['verified','Проверено'],['not_required','Не требуется']].map(([v,t])=>`<option value="${v}" ${status===v?'selected':''}>${t}</option>`).join('')}</select></div>${fs.length?`<p class="file-count">Документов: ${fs.length}</p><div class="documents-list">${ordered.map(f=>fileRow(f,f.id===current.id)).join('')}</div>`:''}${status==='not_required'?'<div class="file-warning">Отмечено как «Не требуется». Загруженные файлы остаются доступны.</div>':''}${!state.current.archived?`<div class="drop-zone ${busy?'busy':''}" data-slot="${slot}" aria-busy="${busy}">${icon('upload')}<p role="status">${busy?`Загружаем ${state.uploading.completed+1} из ${state.uploading.total}: ${esc(state.uploading.name)}`:'Перетащите несколько файлов сюда или выберите на компьютере'}</p><button class="btn small" data-action="choose-file" data-slot="${slot}" ${state.uploading||state.selecting?'disabled':''}>${fs.length?'Добавить документы':'Загрузить документы'}</button><input type="file" multiple hidden data-upload="${slot}" aria-label="Загрузить ${name}" ${state.uploading||state.selecting?'disabled':''}></div>`:''}</section>`;
 }).join('')}</div>`;}
function checksView(){return `<section class="panel"><div class="section-num">ГОТОВНОСТЬ ТОВАРА</div><h2>Проверка перед запуском</h2><p class="subtle">Отмечайте пункты после проверки. Для неприменимых документов укажите статус в разделе файлов.</p><div class="check-progress"><div class="progress-track"><span style="width:${progress(state.current)}%"></span></div><strong id="check-percent">${progress(state.current)}%</strong></div>${CHECKS.map(([key,label,desc])=>`<label class="check-row"><input type="checkbox" data-check="${key}" ${state.current.checks[key]?'checked':''} ${state.current.archived?'disabled':''}><span>${label}<small>${desc}</small></span></label>`).join('')}</section>`+panel('ФИНАЛЬНОЕ СОГЛАСОВАНИЕ','Результат проверки','Укажите, кто подтвердил готовность макета.',field('approvers','Согласовали','Со стороны бренда и завода')+field('approval_date','Дата согласования','ДД.ММ.ГГГГ')+field('changes','Оставшиеся правки','Перечислите правки или укажите «Нет»','textarea',true));}
function historyView(){return `<section class="panel"><h2>История изменений</h2><p class="subtle">Время указано по Москве. Все изменения выполняются через общий аккаунт.</p>${state.activity.length?state.activity.map(a=>`<div class="history-item"><span class="history-dot"></span><div>${esc(a.detail)}<time>${time(a.created_at)}</time></div></div>`).join(''):'<p class="subtle">Изменений пока нет.</p>'}</section>`;}
function stickersView(){
 const p=state.current,locked=p.archived||state.stickerSaving;
 return `<div class="stickers-head"><div><h2 id="stickers-heading">Стикеры</h2><span>Общие заметки по товару</span></div>${!p.archived?`<button class="btn small sticker-add" data-action="add-sticker" ${locked?'disabled':''}>${icon('plus')} Добавить стикер</button>`:''}</div>${state.stickers.length?`<div class="stickers-grid">${state.stickers.map(s=>`<article class="sticker sticker-${Object.hasOwn(STICKER_COLORS,s.color)?s.color:'yellow'}" data-sticker-id="${s.id}"><p class="sticker-text">${esc(s.text)}</p><div class="sticker-footer"><time datetime="${new Date(s.updated_at).toISOString()}">${time(s.updated_at)}</time>${!p.archived?`<div class="sticker-actions"><button type="button" data-action="edit-sticker" data-id="${s.id}" aria-label="Изменить стикер: ${esc(s.text)}" ${locked?'disabled':''}>${icon('edit')} Изменить</button><button type="button" data-action="remove-sticker" data-id="${s.id}" aria-label="Убрать стикер: ${esc(s.text)}" ${locked?'disabled':''}>${icon('check')} Убрать</button></div>`:''}</div></article>`).join('')}</div>`:'<p class="sticker-empty">Добавьте, что ждём по этому товару: согласование, документы или ответ завода.</p>'}`;
}
function renderStickers(){const el=$('#product-stickers');if(el&&state.current)el.innerHTML=stickersView();}
async function refreshStickers(id=state.current?.id){
 if(!id)return;const seq=++stickerReadSeq,stickers=await api(`/products/${id}/stickers`);
 if(state.current?.id===id&&seq===stickerReadSeq){state.stickers=stickers;renderStickers();}
}
function stickerDialog(id){
 if(state.stickerSaving||state.current.archived)return;
 const s=id?state.stickers.find(s=>s.id===id):null;if(id&&!s)return;
 dialog(`${modalHead(s?'Изменить стикер':'Новый стикер')}<p class="subtle">Заметка будет видна всем участникам в этой карточке.</p><form id="sticker-form" data-product-id="${state.current.id}" data-sticker-id="${s?.id||''}" data-revision="${s?.revision||0}"><label class="field"><span>Что нужно помнить или чего ждём</span><textarea name="text" required maxlength="500" rows="4" placeholder="Ждём согласование от Дениса Олеговича">${esc(s?.text||'')}</textarea></label><div class="sticker-counter"><span id="sticker-length">${s?.text.length||0}</span> / 500</div><fieldset class="sticker-colors"><legend>Цвет стикера</legend>${Object.entries(STICKER_COLORS).map(([value,label])=>`<label class="sticker-color"><input type="radio" name="color" value="${value}" ${value===(s?.color||'yellow')?'checked':''}><span class="sticker-swatch sticker-${value}"></span>${label}</label>`).join('')}</fieldset><p class="error" id="modal-error" role="alert"></p><div class="dialog-actions"><button class="btn" type="button" data-action="close">Отмена</button><button class="btn primary" type="submit">${s?'Сохранить стикер':'Добавить стикер'}</button></div></form>`);
}
async function saveSticker(form,values){
 if(state.stickerSaving)return;const productId=form.dataset.productId,id=form.dataset.stickerId;
 state.stickerSaving=true;renderStickers();
 try{
  await api(`/products/${productId}/stickers${id?'/'+id:''}`,{method:id?'PUT':'POST',body:{text:values.text,color:values.color,...(id?{revision:Number(form.dataset.revision),removed:false}:{})}});
  closeModal();if(state.current?.id===productId){await refreshStickers(productId);state.activity=await api(`/products/${productId}/activity`);}toast(id?'Стикер обновлён':'Стикер добавлен');
 }catch(e){if(state.current?.id===productId&&state.session)await refreshStickers(productId).catch(()=>{});throw e;}
 finally{state.stickerSaving=false;renderStickers();}
}
async function removeSticker(id){
 if(state.stickerSaving)return;const s=state.stickers.find(s=>s.id===id);if(!s||state.current.archived)return;
 const productId=state.current.id;state.stickerSaving=true;renderStickers();
 try{const removed=await api(`/products/${productId}/stickers/${id}`,{method:'PUT',body:{text:s.text,color:s.color,revision:s.revision,removed:true}});state.undoSticker=removed;if(state.current?.id===productId){await refreshStickers(productId);state.activity=await api(`/products/${productId}/activity`);}toast('Стикер убран',true);}
 catch(e){if(state.current?.id===productId&&state.session)await refreshStickers(productId).catch(()=>{});throw e;}
 finally{state.stickerSaving=false;renderStickers();}
}
async function undoSticker(){
 const s=state.undoSticker;if(!s||state.stickerSaving)return;state.stickerSaving=true;renderStickers();
 try{await api(`/products/${s.product_id}/stickers/${s.id}`,{method:'PUT',body:{text:s.text,color:s.color,revision:s.revision,removed:false}});state.undoSticker=null;if(state.current?.id===s.product_id){await refreshStickers(s.product_id);state.activity=await api(`/products/${s.product_id}/activity`);}toast('Стикер возвращён');}
 finally{state.stickerSaving=false;renderStickers();}
}
function renderDetail(){const p=state.current;if(!p)return;shell();$('#main').innerHTML=`<div class="topline"><button class="crumb" data-action="back">${icon('arrow')} ${esc(p.line_title||p.title)}</button><span class="tag">${p.archived?'Архивный вариант':'Карточка товара'}</span></div>${variantNav()}<header class="detail-head"><div><h1 id="detail-title">${esc(p.title)}</h1><span class="badge ${p.stage}">${STAGES[p.stage]}</span> <span class="sku">${esc(p.sku||'Артикул не указан')}</span></div><div class="head-actions"><span id="save-note" class="save-note ${state.dirty?'dirty':''}">${state.dirty?'Есть изменения':'Сохранено'}</span><button class="btn primary brief-start" data-action="designer-brief" ${p.archived?'disabled':''}>Собрать ТЗ для дизайнера</button><button class="btn" data-action="export-product" ${state.exporting?'disabled':''}>${icon('download')} Скачать Word</button><button class="btn" data-action="refresh" title="Обновить">${icon('refresh')}</button><button class="btn primary" id="save-btn" data-action="save" ${p.archived?'disabled':''}>${icon('check')} Сохранить</button></div></header><section id="product-stickers" class="sticker-board" aria-labelledby="stickers-heading">${stickersView()}</section><nav class="tabs" aria-label="Разделы карточки">${[['concept','Концепция'],['info','Информация по товару'],['competitors','Конкуренты'],['files','Файлы'],['history','История']].map(([key,label])=>`<button class="tab ${state.tab===key?'active':''}" data-action="tab" data-value="${key}">${label}</button>`).join('')}</nav><div id="detail-body">${({concept,info:productInfo,competitors:competitorsView,files:filesView,history:historyView})[state.tab]()}</div><div class="detail-bottom"><button class="btn subtle-btn" data-action="print">${icon('print')} Распечатать раздел</button><button class="btn subtle-btn" data-action="archive">${icon(p.archived?'refresh':'archive')} ${p.archived?'Восстановить товар':'В архив'}</button></div>`;if(state.tab==='concept')hydrateConceptPhoto();if(state.tab==='info')hydrateMarkImages();if(state.tab==='competitors')hydrateCompetitorPhotos();}
function markDirty(){state.dirty=true;const note=$('#save-note');if(note){note.textContent='Есть изменения';note.classList.add('dirty');}}
async function loadProducts(){const [products,catalog]=await Promise.all([api('/products'),state.catalogReady?Promise.resolve(null):api('/catalog')]);state.products=products.map(p=>({...p,details:normaliseDetails(p.details||{})}));if(catalog){state.factories=catalog.factories;state.markings=catalog.markings;state.catalogReady=true;}}
async function openProduct(id){++stickerReadSeq;const [p,files,activity,stickers]=await Promise.all([api('/products/'+id),api('/products/'+id+'/files'),api('/products/'+id+'/activity'),api('/products/'+id+'/stickers')]);p.details=normaliseDetails(p.details||{});state.current=p;state.line=lineKey(p);state.files=files;state.activity=activity;state.stickers=stickers;state.dirty=false;state.tab='concept';const u=new URL(location.href);u.searchParams.delete('line');u.searchParams.set('product',id);history.replaceState(null,'',u);renderDetail();window.scrollTo(0,0);}
async function save(){if(!state.current)return;const b=$('#save-btn');if(b)b.disabled=true;try{state.current=await api('/products/'+state.current.id,{method:'PUT',body:state.current});state.dirty=false;await loadProducts();state.activity=await api('/products/'+state.current.id+'/activity');const note=$('#save-note');if(note){note.textContent='Сохранено';note.classList.remove('dirty');}renderDetail();toast('Изменения сохранены');}finally{if(b)b.disabled=false;}}
function closeModal(value=false){$('#modal').close();if(modalResolve){const resolve=modalResolve;modalResolve=null;resolve(value);}}
function dialog(html){if(markDraftPreview){URL.revokeObjectURL(markDraftPreview);markDraftPreview=null;}const modal=$('#modal');modal.classList.remove('marks-dialog','brief-dialog');modal.innerHTML=html;if(!modal.open)modal.showModal();setTimeout(()=>$('textarea,input:not([type=hidden])',modal)?.focus(),30);}
function modalHead(title){return `<div class="dialog-head"><h2>${title}</h2><button type="button" data-action="close" aria-label="Закрыть">×</button></div>`;}
async function confirmAction(title,message,label='Продолжить'){dialog(`${modalHead(title)}<p class="subtle">${message}</p><div class="dialog-actions"><button class="btn" data-action="close">Отмена</button><button class="btn primary" data-action="confirm">${label}</button></div>`);return new Promise(resolve=>modalResolve=resolve);}
async function guard(){if(state.photoUploading){toast('Дождитесь загрузки фото');return false;}if(state.markingSaving){toast('Дождитесь сохранения значка');return false;}if(state.exporting){toast('Дождитесь подготовки документа');return false;}if(state.stickerSaving){toast('Дождитесь сохранения стикера');return false;}if(state.uploading||state.selecting){toast('Дождитесь завершения текущей операции с файлами');return false;}if(!state.dirty)return true;dialog(`${modalHead('Сохранить изменения?')}<p class="subtle">В карточке есть несохранённые данные.</p><div class="dialog-actions"><button class="btn" data-action="close">Остаться</button><button class="btn" data-action="discard">Не сохранять</button><button class="btn primary" data-action="save-and-go">Сохранить</button></div>`);const choice=await new Promise(resolve=>modalResolve=resolve);if(choice==='save'){await save();return true;}return choice==='discard';}
function newProduct(){dialog(`${modalHead('Новая линейка')}<p class="subtle">Например, линейка «Листы для стирки», а первый вариант — «Листы для стирки, 30 шт.».</p><form id="new-form"><label class="field"><span>Название линейки</span><input name="line_title" required maxlength="200" placeholder="Листы для стирки"></label><label class="field"><span>Первый вариант товара</span><input name="title" required maxlength="200" placeholder="Листы для стирки, 30 шт."></label><div class="form-grid"><label class="field"><span>Артикул</span><input name="sku" maxlength="100"></label><label class="field"><span>Категория</span><input name="category" maxlength="100"></label></div><p class="error" id="modal-error" role="alert"></p><div class="dialog-actions"><button class="btn" type="button" data-action="close">Отмена</button><button class="btn primary" type="submit">Создать линейку</button></div></form>`);}
function access(){dialog(`${modalHead('Общий логин и пароль')}<p class="subtle">Изменение доступа завершит все открытые сессии. Новый пароль нужно передать участникам команды.</p><form id="access-form"><label class="field"><span>Текущий пароль</span><input name="currentPassword" type="password" required autocomplete="current-password"></label><label class="field"><span>Общий логин</span><input name="login" minlength="3" maxlength="100" value="${esc(state.session.login)}" required autocomplete="username"></label><label class="field"><span>Новый пароль</span><input name="password" type="password" required minlength="12" maxlength="1024" autocomplete="new-password"><em>Минимум 12 символов</em></label><label class="field"><span>Повторите новый пароль</span><input name="repeat" type="password" required autocomplete="new-password"></label><p class="error" id="modal-error" role="alert"></p><div class="dialog-actions"><button class="btn" type="button" data-action="close">Отмена</button><button class="btn primary" type="submit">Обновить доступ</button></div></form>`);}
async function upload(slot,selection){
 const files=Array.from(selection||[]);if(!files.length)return;
 if(state.uploading||state.selecting)throw new Error('Дождитесь завершения текущей операции с файлами');
 for(const file of files){if(file.size>25*1024*1024)throw new Error(`«${file.name}»: максимальный размер файла — 25 МБ`);if(!file.size)throw new Error(`«${file.name}»: нельзя загрузить пустой файл`);}
 const id=state.current.id;let uploaded=0,failure;
 state.uploading={slot,completed:0,total:files.length,name:files[0].name};renderDetail();
 try{
  for(const file of files){
   state.uploading.name=file.name;state.uploading.completed=uploaded;if(state.current?.id===id)renderDetail();
   try{await api(`/products/${id}/files?slot=${slot}`,{method:'POST',body:file,headers:{'X-File-Name':encodeURIComponent(file.name),'Content-Type':'application/octet-stream'}});uploaded++;}catch(e){failure=e;break;}
  }
  if(state.session&&state.current?.id===id){try{const [saved,activity]=await Promise.all([api(`/products/${id}/files`),api(`/products/${id}/activity`)]);if(state.current?.id===id){state.files=saved;state.activity=activity;}}catch(e){failure=failure||e;}}
  if(failure)throw new Error(`Загружено ${uploaded} из ${files.length}. ${failure.message}${uploaded<files.length?' Остальные файлы не загружены.':''}`);
  toast(`Загружено документов: ${uploaded}. Актуальный документ можно выбрать в списке.`);
 }finally{state.uploading=null;if(state.current?.id===id)renderDetail();}
}
async function setCurrent(id){
 if(state.uploading||state.selecting)throw new Error('Дождитесь завершения текущей операции с файлами');
 const productId=state.current.id;state.selecting=id;renderDetail();
 try{await api('/files/'+id+'/current',{method:'POST'});const [files,activity]=await Promise.all([api(`/products/${productId}/files`),api(`/products/${productId}/activity`)]);if(state.current?.id===productId){state.files=files;state.activity=activity;}toast('Актуальный документ выбран');}
 finally{state.selecting=null;if(state.current?.id===productId)renderDetail();}
}
async function download(id,preview=false){const f=state.files.find(x=>x.id===id);if(!f)return;const blob=await api('/files/'+id+(preview?'?preview=1':''),{binary:true});const url=URL.createObjectURL(blob);if(preview){dialog(`${modalHead('Фото товара')}<img class="dialog-img" src="${url}" alt="${esc(f.name)}"><p class="subtle">${esc(f.name)}</p>`);$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}else{const a=document.createElement('a');a.href=url;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}}
async function action(name,el){switch(name){
 case 'show-password':{const input=$('input',el.parentElement);input.type=input.type==='password'?'text':'password';el.textContent=input.type==='password'?'Показать':'Скрыть';el.setAttribute('aria-label',el.textContent+' пароль');break;}
 case 'close':if(state.photoReturnBrief){state.photoReturnBrief=false;renderBrief();break;}if($('#brief-editor')){closeBrief();break;}if(state.markingSaving){toast('Дождитесь сохранения значка');break;}renderMarkBoxes();closeModal(false);break;case 'confirm':closeModal(true);break;case 'discard':closeModal('discard');break;case 'save-and-go':closeModal('save');break;
 case 'filter':if(await guard()){state.filter=el.dataset.value;await loadProducts();renderList();}break;
 case 'back':if(await guard()){const key=lineKey(state.current);await loadProducts();renderLine(key);}break;
 case 'new':if(await guard())newProduct();break;
 case 'all-lines':if(await guard()){await loadProducts();renderList();}break;
 case 'open-line':if(await guard())renderLine(el.dataset.id);break;
 case 'add-variant':if(await guard())variantDialog(el.dataset.id);break;
 case 'rename-line':renameLine(el.dataset.id);break;
 case 'new-factory':factoryDialog();break;
 case 'choose-marks':await chooseMarks(el.dataset.kind);break;
 case 'new-mark':newMarkDialog(el.dataset.kind);break;
 case 'back-to-marks':if(!state.markingSaving)await chooseMarks(el.dataset.kind,false);break;
 case 'finish-marks':renderMarkBoxes();closeModal();break;
 case 'copy-text':await copyProductText(el.dataset.kind);break;
 case 'add-competitor':state.current.details.competitors.push({id:'r'+Date.now().toString(36)+Math.random().toString(36).slice(2,9),brand:'',url:'',advantages:'',packaging:'',stores:'',price:''});markDirty();renderDetail();break;
 case 'remove-competitor':state.current.details.competitors=state.current.details.competitors.filter(r=>r.id!==el.dataset.id);markDirty();renderDetail();break;
 case 'export-product':await exportProduct();break;
 case 'designer-brief':await openDesignerBrief();break;
 case 'choose-competitor-photo':$('[data-competitor-upload="'+el.dataset.id+'"]').click();break;
 case 'view-competitor-photo':await viewCompetitorPhoto(el.dataset.photo,el.dataset.name);break;
 case 'remove-competitor-photo':{const row=state.current.details.competitors.find(r=>r.id===el.dataset.id);if(row){row.photo_id='';markDirty();renderDetail();}break;}
 case 'save-brief':await saveDesignerBrief();break;
 case 'download-brief':await downloadDesignerBrief();break;
 case 'stay-brief':$('#brief-close-confirm').hidden=true;break;
 case 'discard-brief':state.briefDirty=false;closeModal();break;
 case 'save-close-brief':if(await saveDesignerBrief())closeModal();break;
 case 'rebuild-brief':$('#brief-rebuild-confirm').hidden=false;break;
 case 'cancel-rebuild-brief':$('#brief-rebuild-confirm').hidden=true;break;
 case 'confirm-rebuild-brief':if(!state.briefBusy){briefLock(true);try{state.brief=await api(`/products/${state.current.id}/designer-brief?fresh=1`);state.briefDirty=true;renderBrief();}finally{briefLock(false);}}break;
 case 'add-brief-section':if(state.brief.content.sections.length>=25){toast('Не более 25 разделов');break;}state.brief.content.sections.push({id:'section_'+Date.now().toString(36),title:'Новый раздел',text:''});markBriefDirty();renderBrief();break;
 case 'remove-brief-section':state.brief.content.sections=state.brief.content.sections.filter(s=>s.id!==el.dataset.id);markBriefDirty();renderBrief();break;
 case 'remove-brief-competitor':state.brief.content.competitors=state.brief.content.competitors.filter(r=>r.id!==el.dataset.id);markBriefDirty();renderBrief();break;
 case 'open':if(await guard())await openProduct(el.dataset.id);break;
 case 'save':await save();break;
 case 'tab':state.tab=el.dataset.value;renderDetail();break;
 case 'refresh':if(await guard())await openProduct(state.current.id);break;
 case 'choose-file':$(`[data-upload="${el.dataset.slot}"]`).click();break;
 case 'download':await download(el.dataset.id);break;case 'preview':await download(el.dataset.id,true);break;
 case 'add-sticker':stickerDialog();break;
 case 'edit-sticker':stickerDialog(el.dataset.id);break;
 case 'remove-sticker':await removeSticker(el.dataset.id);break;
 case 'undo-sticker':await undoSticker();break;
 case 'set-current':await setCurrent(el.dataset.id);break;
 case 'archive':if(await guard()){const archived=state.current.archived;if(await confirmAction(archived?'Восстановить товар?':'Переместить товар в архив?',archived?'Карточка вернётся в общий список.':'Карточка и файлы сохранятся в архиве.',archived?'Восстановить':'В архив')){state.current.archived=!archived;await save();renderList();}}break;
 case 'access':if(await guard())access();break;
 case 'logout':if(await guard()){await api('/logout',{method:'POST'});storeSession(null);state.current=null;state.dirty=false;renderLogin();}break;
 case 'print':window.print();break;
 }}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const name=el.dataset.action;if(['download','preview','set-current','save','refresh','export-product'].includes(name)){el.disabled=true;action(name,el).catch(e=>toast(e.message)).finally(()=>el.disabled=false);}else action(name,el).catch(e=>toast(e.message));});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.product-card')){e.preventDefault();action(e.target.dataset.action,e.target).catch(e=>toast(e.message));}});
document.addEventListener('input',e=>{
 const el=e.target;
 if(state.brief&&el.closest('#brief-editor')){if(el.hasAttribute('data-brief-title'))state.brief.content.title=el.value;else if(el.dataset.briefSection)state.brief.content.sections.find(s=>s.id===el.dataset.briefSection).text=el.value;else if(el.dataset.briefSectionTitle){const section=state.brief.content.sections.find(s=>s.id===el.dataset.briefSectionTitle);section.title=el.value;el.closest('details').querySelector('summary').textContent=el.value;}else if(el.dataset.briefCompetitor)state.brief.content.competitors.find(r=>r.id===el.dataset.briefCompetitor)[el.dataset.column]=el.value;else return;markBriefDirty();return;}
 if(el.name==='text'&&el.closest('#sticker-form')){$('#sticker-length').textContent=el.value.length;return;}
 if(el.id==='search'){state.search=el.value;renderCards();return;}
 if(el.id==='marks-search'){filterMarks();return;}
 if(!state.current)return;
 if(el.dataset.translation){state.current.details.translations[el.dataset.translation].text=el.value;markDirty();renderGenerated();return;}
 if(el.dataset.competitor){const row=state.current.details.competitors.find(r=>r.id===el.dataset.competitor);if(row){row[el.dataset.column]=el.value;markDirty();if(el.dataset.column==='url'){let a=el.parentElement.querySelector('a');if(/^https?:\/\/[^\s]+$/i.test(el.value)){if(!a){a=document.createElement('a');a.textContent='Открыть товар ↗';a.target='_blank';a.rel='noopener noreferrer';el.parentElement.append(a);}a.href=el.value;a.hidden=false;}else if(a)a.hidden=true;}}return;}
 if(!el.dataset.field)return;const k=el.dataset.field;if(['title','sku','category','stage'].includes(k))state.current[k]=el.value;else state.current.fields[k]=el.value;markDirty();
});
document.addEventListener('change',e=>{
 const el=e.target;
 if(el.dataset.briefOption&&state.brief){state.brief.content[el.dataset.briefOption]=el.checked;markBriefDirty();return;}
 if(el.dataset.competitorUpload){uploadCompetitorPhoto(el.dataset.competitorUpload,el.files[0]).catch(e=>toast(e.message));return;}
 if(el.id==='marking-image'){if(markDraftPreview)URL.revokeObjectURL(markDraftPreview);markDraftPreview=el.files[0]?URL.createObjectURL(el.files[0]):null;const img=$('#custom-mark-preview');if(markDraftPreview){img.src=markDraftPreview;img.hidden=false;}else{img.removeAttribute('src');img.hidden=true;}return;}
 if(el.id==='sort'){state.sort=el.value;renderCards();return;}
 if(el.id==='marks-category'){filterMarks();return;}
 if(el.dataset.upload){upload(el.dataset.upload,el.files).catch(e=>toast(e.message));return;}
 if(!state.current)return;
 if(el.dataset.detailList){const key=el.dataset.detailList,values=state.current.details[key];state.current.details[key]=el.checked?[...new Set([...values,el.value])]:values.filter(x=>x!==el.value);markDirty();renderGenerated();return;}
 if(el.dataset.language){state.current.details.translations[el.dataset.language].enabled=el.checked;$('#translations-body').innerHTML=translationPanels();markDirty();return;}
 if(el.dataset.markId){const key=el.dataset.markKind,values=state.current.details[key];state.current.details[key]=el.checked?[...new Set([...values,el.dataset.markId])]:values.filter(x=>x!==el.dataset.markId);markDirty();return;}
 if(el.matches('select[data-field]')){const k=el.dataset.field;if(k==='stage')state.current.stage=el.value;else state.current.fields[k]=el.value;markDirty();}
});
document.addEventListener('dragover',e=>{const z=e.target.closest('.drop-zone');if(z){e.preventDefault();z.classList.add('drag');}});
document.addEventListener('dragleave',e=>{e.target.closest('.drop-zone')?.classList.remove('drag');});
document.addEventListener('drop',e=>{const z=e.target.closest('.drop-zone');if(z){e.preventDefault();z.classList.remove('drag');upload(z.dataset.slot,e.dataTransfer.files).catch(e=>toast(e.message));}});
document.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target,b=e.submitter,values=Object.fromEntries(new FormData(form));if(b)b.disabled=true;const error=$(form.id==='login-form'?'#login-error':'#modal-error');if(error)error.textContent='';
 try{
  if(form.id==='login-form'){values.login=values.login.trim();const result=await api('/login',{method:'POST',body:values});storeSession(result);await loadProducts();const u=new URL(location.href);if(u.searchParams.get('product'))await openProduct(u.searchParams.get('product'));else if(u.searchParams.get('line'))renderLine(u.searchParams.get('line'));else renderList();}
  if(form.id==='new-form'){const p=await api('/products',{method:'POST',body:values});closeModal();await loadProducts();await openProduct(p.id);toast('Линейка и первый вариант созданы');}
  if(form.id==='variant-form'){const p=await api('/products/'+values.source+'/variants',{method:'POST',body:{title:values.title}});closeModal();await loadProducts();await openProduct(p.id);toast('Вариант добавлен. Заполните артикул, штрихкоды, вложимость и загрузите макеты.');}
  if(form.id==='line-form'){await api('/lines/'+form.dataset.id,{method:'PUT',body:{title:values.title,revision:Number(form.dataset.revision)}});closeModal();await loadProducts();renderLine(form.dataset.id);toast('Название линейки сохранено');}
  if(form.id==='factory-form'){const f=await api('/factories',{method:'POST',body:values});state.factories.push(f);state.current.details.factory_ids.push(f.id);markDirty();closeModal();renderDetail();toast('Завод добавлен и выбран. Сохраните карточку товара.');}
  if(form.id==='marking-form')await saveMark(form,values);
  if(form.id==='sticker-form')await saveSticker(form,values);
  if(form.id==='access-form'){if(values.password!==values.repeat)throw new Error('Новые пароли не совпадают');await api('/access',{method:'PUT',body:values});closeModal();storeSession(null);state.current=null;state.dirty=false;renderLogin();toast('Доступ обновлён. Войдите с новым паролем.');}
 }catch(e){if(error)error.textContent=e.message;else toast(e.message);}finally{if(b)b.disabled=false;}
});
$('#modal').addEventListener('cancel',e=>{if(state.photoReturnBrief){e.preventDefault();state.photoReturnBrief=false;renderBrief();return;}if($('#brief-editor')){e.preventDefault();closeBrief();return;}if(state.markingSaving){e.preventDefault();return;}if(modalResolve){modalResolve(false);modalResolve=null;}});
$('#modal').addEventListener('close',()=>{if($('#brief-editor')){state.brief=null;state.briefDirty=false;}if(markDraftPreview){URL.revokeObjectURL(markDraftPreview);markDraftPreview=null;}$('#modal').classList.remove('marks-dialog');renderMarkBoxes();});
window.addEventListener('beforeunload',e=>{if(state.dirty||state.uploading||state.selecting||state.stickerSaving||state.exporting||state.markingSaving||state.photoUploading||state.briefDirty||state.briefBusy){e.preventDefault();e.returnValue='';}});
async function start(){if(!state.session){renderLogin();return;}try{const current=await api('/session');state.session.login=current.login;await loadProducts();const id=new URL(location.href).searchParams.get('product');if(id)await openProduct(id);else{const key=new URL(location.href).searchParams.get('line');key?renderLine(key):renderList();}}catch(e){if(!state.session)renderLogin(e.message);else{$('#app').innerHTML=`<div class="login-form" style="min-height:100dvh"><div class="login-box">${brand()}<h2>Не удалось открыть кабинет</h2><p class="subtle">${esc(e.message)}</p><button class="btn primary" id="retry">Повторить</button></div></div>`;$('#retry').onclick=()=>start();}}}
function pollStickers(){if(state.current&&state.session&&!state.stickerSaving&&!document.hidden&&!$('#modal').open)refreshStickers().catch(()=>{});}
window.addEventListener('focus',pollStickers);
setInterval(pollStickers,30000);
start();
